/* ============== chat love notes ============== */
const notes = [
  "you get so gentle and soft with me, even when I'm being extra 🥹",
  "you've turned dumb memes into our entire love language",
  "you cry during anime and then swear you didn't 😭💜",
  "you're the most caring, sweetest person I've ever met",
  "our voice notes about literally nothing, at 2am, every night",
  "you make an ordinary Tuesday feel like a drama finale",
  "you send reels faster than I can even open the last one",
  "you. just you. that's the whole reel."
];
const thread = document.getElementById('thread');
const progressEl = document.getElementById('threadProgress');
let opened = 0;
notes.forEach((note,i)=>{
  const btn = document.createElement('button');
  btn.className = 'bubble-btn';
  btn.innerHTML = `Love note #${i+1}<span class="tap-hint">tap to open</span>`;
  btn.addEventListener('click', ()=>{
    if(btn.classList.contains('opened')) return;
    btn.classList.add('opened');
    btn.innerHTML = note;
    opened++;
    progressEl.textContent = opened + ' / 8 opened';
  });
  thread.appendChild(btn);
});

/* ============== counter ============== */
const startDateInput = document.getElementById('startDate');
const counterResults = document.getElementById('counterResults');
const statDays = document.getElementById('statDays');
const statMemes = document.getElementById('statMemes');
const statAnime = document.getElementById('statAnime');
startDateInput.addEventListener('change', ()=>{
  const val = startDateInput.value;
  if(!val) return;
  const start = new Date(val);
  const now = new Date();
  const diffDays = Math.max(0, Math.floor((now - start) / (1000*60*60*24)));
  statDays.textContent = diffDays.toLocaleString();
  statMemes.textContent = (diffDays * 3).toLocaleString();
  statAnime.textContent = Math.max(1, Math.floor(diffDays/5)).toLocaleString();
  counterResults.style.display = 'grid';
});

/* ============== quiz ============== */
const quizData = [
  {
    q: "What color does Princess love most?",
    opts: ["Lavender", "Neon Orange", "Jet Black", "Mustard Yellow"],
    correct: 0
  },
  {
    q: 'What do Jerald and Princess call each other?',
    opts: ["Boss", "Love", "Ma'am/Sir", "Bestie"],
    correct: 1
  },
  {
    q: "What do they binge together on lazy nights?",
    opts: ["Sports highlights", "Anime, movies & dramas", "Cooking tutorials", "The news"],
    correct: 1
  },
  {
    q: "What's basically their main love language?",
    opts: ["Sending meme & sweet reels all day", "Formal emails", "Morse code", "Silence"],
    correct: 0
  },
  {
    q: "What's their most photographed pose?",
    opts: ["Solo mirror selfies", "Heart hands & squished cheeks", "Business headshots", "Passport photo face"],
    correct: 1
  }
];
let quizIndex = 0;
let quizScore = 0;
const quizBody = document.getElementById('quizBody');
const quizProgress = document.getElementById('quizProgress');
const quizResult = document.getElementById('quizResult');
const quizResultTitle = document.getElementById('quizResultTitle');
const quizResultText = document.getElementById('quizResultText');

function renderQuiz(){
  quizBody.innerHTML = '';
  const item = quizData[quizIndex];
  quizProgress.textContent = `Question ${quizIndex+1} of ${quizData.length}`;
  const wrap = document.createElement('div');
  wrap.className = 'quiz-q active';
  const h3 = document.createElement('h3');
  h3.textContent = item.q;
  wrap.appendChild(h3);
  item.opts.forEach((opt,i)=>{
    const b = document.createElement('button');
    b.className = 'quiz-opt';
    b.textContent = opt;
    b.addEventListener('click', ()=>{
      const allBtns = wrap.querySelectorAll('.quiz-opt');
      allBtns.forEach(bb=>bb.style.pointerEvents='none');
      if(i === item.correct){
        b.classList.add('correct');
        quizScore++;
      } else {
        b.classList.add('wrong');
        allBtns[item.correct].classList.add('correct');
      }
      setTimeout(()=>{
        quizIndex++;
        if(quizIndex < quizData.length){
          renderQuiz();
        } else {
          showQuizResult();
        }
      }, 850);
    });
    wrap.appendChild(b);
  });
  quizBody.appendChild(wrap);
}

function showQuizResult(){
  quizProgress.textContent = 'Results';
  quizBody.style.display = 'none';
  quizResult.classList.add('active');
  const pct = quizScore / quizData.length;
  if(pct === 1){
    quizResultTitle.textContent = "Perfect score, Love 💯";
    quizResultText.textContent = "You know us better than we know ourselves. Certified soulmate behavior.";
  } else if(pct >= 0.6){
    quizResultTitle.textContent = "Pretty much an expert on us";
    quizResultText.textContent = "A few misses, but the important stuff? You nailed it.";
  } else {
    quizResultTitle.textContent = "We should talk more, Love";
    quizResultText.textContent = "Good excuse for more voice notes and more reels, honestly.";
  }
}
renderQuiz();

/* ============== finale confetti ============== */
document.getElementById('surpriseBtn').addEventListener('click', ()=>{
  const letter = document.getElementById('letter');
  letter.classList.add('show');
  const emojis = ['💜','✨','🌸','💮','💌'];
  for(let i=0;i<40;i++){
    setTimeout(()=>{
      const c = document.createElement('div');
      c.className = 'confetti-piece';
      c.textContent = emojis[Math.floor(Math.random()*emojis.length)];
      c.style.left = Math.random()*100 + 'vw';
      c.style.animationDuration = (2.4 + Math.random()*1.6) + 's';
      document.body.appendChild(c);
      setTimeout(()=>c.remove(), 4200);
    }, i*40);
  }
});
